var DATA = {"mode": "pins", "cable": "24-pin ATX", "pins": 24};
function show(k,v){console.log(k+": "+v);}
var m=DATA.mode;
if(m==="pins"){
  show("Cable",DATA.cable);
  show("Pins",DATA.pins);
  show("Comb",DATA.pins+"-slot");
}else if(m==="pick"){
  show("For",DATA.cable);
  show("Pick",DATA.pick);
}else if(m==="count"){
  show("Combs per cable",DATA.per);
  show("Cables",DATA.cables);
  show("Total combs",DATA.per*DATA.cables);
}else if(m==="install"){
  console.log("Install order:");DATA.steps.forEach(function(s,i){console.log("  "+(i+1)+". "+s);});
}else if(m==="types"){
  console.log("Comb types:");DATA.types.forEach(function(t){console.log("  "+t);});
}else if(m==="spacing"){
  show("First comb",DATA.a+" cm from the connector");
  show("Then every",DATA.every+" cm");
}else if(m==="material"){
  show("Material",DATA.mat);
  show("Edges","smooth - never nicks wire insulation");
}else if(m==="color"){
  show("Colors",DATA.colors.join(", "));
  show("Advice","match the build or go clear");
}else if(m==="open"){
  show("Open combs","snap on after routing");
  show("Closed combs","thread onto wires before the connector");
}else if(m==="care"){
  show("Cleaning","wipe with a damp cloth");
  show("Sunlight","keep out of direct UV");
}else if(m==="mistake"){
  show("Mistake",DATA.bad);show("Instead",DATA.good);
}else if(m==="workflow"){
  console.log("Combing workflow:");DATA.steps.forEach(function(s,i){console.log("  "+(i+1)+". "+s);});
}
